command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: FLEDERMAUSLEIB (BRONA)
//
// - sichere GM-Verarbeitung
// - normale Spieler können die Gabe ausführen
// - Fledermaus wird nur einmal importiert
// - vorhandener Import wird wiederverwendet
// - Spielerrechte werden vorübergehend vergeben
// - unverknüpfter Token mit eigenen Werten
// - Sicht des Wirkenden wird übernommen
// - Bewegungsaktion wird auf Fliegen gesetzt
// - LeP und AeP prozentual verbunden
// - Haupteffekt vollständig über Block 5
// - Wirkungsende über Block 6
// - gemeinsame Karte über Block 19.8
// - roter GM-Button „Effekt anwenden“
// - dieselbe Karte wird aktualisiert
// - automatische Rückverwandlung
// ==========================================

(async function () {
    const macroUuid = this?.uuid || game.macros.getName("Fledermausleib")?.uuid || null;

    // +++ 1 - FRAMEWORK +++++++++++++++++++++++++++++++++++++++

    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";
    const frameworkFehlt =
        !globalThis.DSK?.Effekt?.Anwenden || !globalThis.DSK?.EffektEnde?.Register ||
        !globalThis.DSK?.QS?.Ermitteln || !globalThis.DSK?.Token?.Finde ||
        !globalThis.DSK?.Empfaenger?.Besitzer ||
        !globalThis.DSK?.GMAnfrage?.Speichern || !globalThis.DSK?.GMAnfrage?.Finden ||
        !globalThis.DSK?.GMAnfrage?.Lesen || !globalThis.DSK?.GMAnfrage?.Loeschen ||
        !globalThis.DSK?.GabenUI?.GMMakroButton ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteErstellen ||
        !globalThis.DSK?.GabenUI?.AnfrageKarteAktualisieren;

    if (frameworkFehlt) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (!fwMacro) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht gefunden!");
        await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    const DSK_FW = globalThis.DSK;

    if (
        !DSK_FW?.Effekt?.Anwenden || !DSK_FW?.EffektEnde?.Register ||
        !DSK_FW?.QS?.Ermitteln || !DSK_FW?.Token?.Finde ||
        !DSK_FW?.Empfaenger?.Besitzer ||
        !DSK_FW?.GMAnfrage?.Speichern || !DSK_FW?.GMAnfrage?.Finden ||
        !DSK_FW?.GMAnfrage?.Lesen || !DSK_FW?.GMAnfrage?.Loeschen ||
        !DSK_FW?.GabenUI?.GMMakroButton ||
        !DSK_FW?.GabenUI?.AnfrageKarteErstellen ||
        !DSK_FW?.GabenUI?.AnfrageKarteAktualisieren
    ) return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++

    const gabenName = "Fledermausleib", vollerName = "Fledermausleib (Brona)", ahne = "Brona";
    const fledermausUuid = "Compendium.dsk-bestiary.bestiarybestiary.Actor.fyR7KUkSiOC6z5ga";
    const flagKey = "pendingFledermausleibBrona", quellFlag = "fledermausleibQuelle";
    const basisRechteFlag = "fledermausleibBasisRechte", sitzungenFlag = "fledermausleibSitzungen";
    const endeKey = "bronaFledermausleib";
    const endeText = "Der Fledermausleib vergeht, und der ursprüngliche Körper kehrt zurück.";
    const symbolPfad = DSK_FW.Symbol(ahne);
    const basisBeschreibung =
        `Der Leib der Vampirkatze zerfällt in Fledermäuse, die davonfliegen. Eine dieser Fledermäuse ist der Wirkende.` +
        `<br><br>LeP und AeP bleiben während der Verwandlung <b>prozentual miteinander verbunden</b>.` +
        `<br><br>Die Fledermaus übernimmt die Sicht des Wirkenden und verwendet die Bewegungsaktion <b>Fliegen</b>.` +
        `<br><br>Während der Verwandlung können keine weiteren Ahnengaben gewirkt werden.`;

    DSK_FW.EffektEnde.Register(endeKey, vollerName, endeText);

    // +++ 3 - HILFSFUNKTIONEN +++++++++++++++++++++++++++++++++

    const istAktiverGM = () => {
        const aktiverGM = game.users.find(user => user.isGM && user.active);
        return aktiverGM ? game.user.isGM && game.user.id === aktiverGM.id : game.user.isGM;
    };

    const begrenze = (wert, minimum, maximum) => Math.max(minimum, Math.min(maximum, Number(wert) || 0));

    const liesStat = (actor, stat) => {
        const daten = foundry.utils.getProperty(actor, `system.stats.${stat}`);
        return { value: Number(daten?.value ?? 0), max: Math.max(1, Number(daten?.max ?? 1)) };
    };

    const berechneProzentwert = ({ quellWert, quellMaximum, zielMaximum, minimum = 0 }) => {
        const prozent = begrenze(Number(quellWert ?? 0) / Math.max(1, Number(quellMaximum ?? 1)), 0, 1);
        return Math.max(minimum, Math.round(Math.max(1, Number(zielMaximum ?? 1)) * prozent));
    };

    const raeumeQSAuf = async actor => {
        if (actor?.getFlag("world", "letzteGabenQS") !== undefined) await actor.unsetFlag("world", "letzteGabenQS");
        if (actor?.getFlag("world", "letzteGabenMessageId") !== undefined) await actor.unsetFlag("world", "letzteGabenMessageId");
    };

    const ladeActor = async uuid => {
        if (!uuid) return null;
        try {
            const dokument = await fromUuid(uuid);
            return dokument?.documentName === "Token" ? dokument.actor : dokument || null;
        } catch (error) {
            console.warn("Fledermausleib: Akteur konnte nicht geladen werden.", { uuid, error });
            return null;
        }
    };

    const ladeTokenDokument = async ({ tokenUuid = null, tokenId = null, sceneId = null } = {}) => {
        if (tokenUuid) {
            try {
                const dokument = await fromUuid(tokenUuid);
                if (dokument?.documentName === "Token") return dokument;
            } catch (error) {
                console.warn("Fledermausleib: Token konnte nicht über UUID geladen werden.", { tokenUuid, error });
            }
        }

        return (game.scenes.get(sceneId) || canvas.scene)?.tokens.get(tokenId) || null;
    };

    const findeImportierteFledermaus = () => game.actors.find(actor =>
        actor.getFlag("dsk", quellFlag) === fledermausUuid ||
        actor.getFlag("core", "sourceId") === fledermausUuid
    ) || null;

    // +++ 4 - FLEDERMAUS IMPORTIEREN ++++++++++++++++++++++++++

    const ladeOderImportiereFledermaus = async () => {
        let fledermausActor = findeImportierteFledermaus();

        if (fledermausActor) {
            if (fledermausActor.getFlag("dsk", quellFlag) !== fledermausUuid) {
                await fledermausActor.setFlag("dsk", quellFlag, fledermausUuid);
            }
            return fledermausActor;
        }

        const kompendiumActor = await fromUuid(fledermausUuid);
        if (!kompendiumActor) throw new Error(`Fledermaus nicht gefunden: ${fledermausUuid}`);

        const importDaten = kompendiumActor.toObject();
        delete importDaten._id;
        delete importDaten.folder;
        delete importDaten.sort;

        foundry.utils.setProperty(importDaten, `flags.dsk.${quellFlag}`, fledermausUuid);
        foundry.utils.setProperty(importDaten, "flags.core.sourceId", fledermausUuid);

        fledermausActor = await Actor.create(importDaten, { renderSheet: false });
        if (!fledermausActor) throw new Error("Der Fledermaus-Akteur konnte nicht importiert werden.");
        return fledermausActor;
    };

    // +++ 5 - RECHTEVERWALTUNG ++++++++++++++++++++++++++++++++

    const baueAktuelleRechte = ({ basisRechte = {}, sitzungen = {} } = {}) => {
        const ownership = foundry.utils.deepClone(basisRechte);

        for (const sitzung of Object.values(sitzungen)) {
            for (const userId of sitzung?.userIds || []) {
                if (game.users.get(userId)) ownership[userId] = CONST.DOCUMENT_OWNERSHIP_LEVELS.OWNER;
            }
        }

        return ownership;
    };

    const fuegeRechteSitzungHinzu = async ({ fledermausActor, sessionId, userIds = [] }) => {
        if (!fledermausActor || !sessionId) return false;

        const sitzungen = foundry.utils.deepClone(fledermausActor.getFlag("dsk", sitzungenFlag) || {});
        let basisRechte = fledermausActor.getFlag("dsk", basisRechteFlag);

        if (!basisRechte || !Object.keys(sitzungen).length) {
            basisRechte = foundry.utils.deepClone(fledermausActor.ownership || {});
        }

        sitzungen[sessionId] = { userIds: [...new Set(userIds)], erstellt: Date.now() };

        await fledermausActor.update({
            ownership: baueAktuelleRechte({ basisRechte, sitzungen }),
            [`flags.dsk.${quellFlag}`]: fledermausUuid,
            [`flags.dsk.${basisRechteFlag}`]: basisRechte,
            [`flags.dsk.${sitzungenFlag}`]: sitzungen
        });

        return true;
    };

    const entferneRechteSitzung = async ({ fledermausActor, sessionId }) => {
        if (!fledermausActor || !sessionId) return false;

        const sitzungen = foundry.utils.deepClone(fledermausActor.getFlag("dsk", sitzungenFlag) || {});
        const basisRechte = fledermausActor.getFlag("dsk", basisRechteFlag);
        delete sitzungen[sessionId];

        if (!Object.keys(sitzungen).length) {
            await fledermausActor.update({ ownership: foundry.utils.deepClone(basisRechte || fledermausActor.ownership || {}) });
            if (fledermausActor.getFlag("dsk", basisRechteFlag) !== undefined) await fledermausActor.unsetFlag("dsk", basisRechteFlag);
            if (fledermausActor.getFlag("dsk", sitzungenFlag) !== undefined) await fledermausActor.unsetFlag("dsk", sitzungenFlag);
            return true;
        }

        await fledermausActor.update({
            ownership: baueAktuelleRechte({ basisRechte: basisRechte || fledermausActor.ownership || {}, sitzungen }),
            [`flags.dsk.${sitzungenFlag}`]: sitzungen
        });

        return true;
    };

    // +++ 6 - FLEDERMAUS-TOKEN ERZEUGEN ++++++++++++++++++++++

    const erzeugeFledermausToken = async ({ casterActor, casterToken, fledermausActor, sessionId }) => {
        const casterLeP = liesStat(casterActor, "LeP"), casterAeP = liesStat(casterActor, "AeP");
        const fledermausLeP = liesStat(fledermausActor, "LeP"), fledermausAeP = liesStat(fledermausActor, "AeP");

        const startLeP = berechneProzentwert({
            quellWert: casterLeP.value, quellMaximum: casterLeP.max,
            zielMaximum: fledermausLeP.max, minimum: casterLeP.value > 0 ? 1 : 0
        });

        const startAeP = berechneProzentwert({
            quellWert: casterAeP.value, quellMaximum: casterAeP.max,
            zielMaximum: fledermausAeP.max, minimum: 0
        });

        const tokenVorlage = await fledermausActor.getTokenDocument({
            x: casterToken.document.x, y: casterToken.document.y,
            elevation: casterToken.document.elevation || 0,
            hidden: false, actorLink: false
        });

        if (!tokenVorlage) throw new Error("Die Fledermaus-Tokenvorlage konnte nicht erzeugt werden.");

        const tokenDaten = tokenVorlage.toObject();
        delete tokenDaten._id;

        Object.assign(tokenDaten, {
            x: casterToken.document.x, y: casterToken.document.y,
            elevation: casterToken.document.elevation || 0,
            hidden: false, actorId: fledermausActor.id, actorLink: false,
            movementAction: "fly",
            disposition: casterToken.document.disposition,
            displayName: casterToken.document.displayName,
            displayBars: casterToken.document.displayBars
        });

        tokenDaten.sight = foundry.utils.deepClone(casterToken.document.sight?.toObject?.() || casterToken.document.sight || {});
        tokenDaten.detectionModes = foundry.utils.deepClone(Array.from(casterToken.document.detectionModes || [])
            .map(modus => modus?.toObject?.() || foundry.utils.deepClone(modus)));
        tokenDaten.light = foundry.utils.deepClone(casterToken.document.light?.toObject?.() || casterToken.document.light || {});
        tokenDaten.delta = foundry.utils.deepClone(tokenDaten.delta || {});

        foundry.utils.setProperty(tokenDaten, "delta.system.stats.LeP.value", startLeP);
        foundry.utils.setProperty(tokenDaten, "delta.system.stats.AeP.value", startAeP);
        foundry.utils.setProperty(tokenDaten, "delta.flags.dsk.fledermausleib", true);
        foundry.utils.setProperty(tokenDaten, "delta.flags.dsk.isFledermausVon", casterActor.uuid);
        foundry.utils.setProperty(tokenDaten, "delta.flags.dsk.fledermausleibSessionId", sessionId);

        foundry.utils.setProperty(tokenDaten, "flags.dsk.fledermausleib", true);
        foundry.utils.setProperty(tokenDaten, "flags.dsk.isFledermausVon", casterActor.uuid);
        foundry.utils.setProperty(tokenDaten, "flags.dsk.fledermausleibSessionId", sessionId);
        foundry.utils.setProperty(tokenDaten, "flags.dsk.originalTokenUuid", casterToken.document.uuid);

        const [fledermausToken] = await canvas.scene.createEmbeddedDocuments("Token", [tokenDaten]);

        if (!fledermausToken?.actor) {
            if (fledermausToken) await canvas.scene.deleteEmbeddedDocuments("Token", [fledermausToken.id]);
            throw new Error("Der synthetische Fledermaus-Akteur konnte nicht erzeugt werden.");
        }

        await fledermausToken.actor.update({
            "system.stats.LeP.value": startLeP, "system.stats.AeP.value": startAeP,
            "flags.dsk.fledermausleib": true, "flags.dsk.isFledermausVon": casterActor.uuid,
            "flags.dsk.fledermausleibSessionId": sessionId
        }, { dskFledermausSetup: true });

        if (fledermausToken.movementAction !== "fly") await fledermausToken.update({ movementAction: "fly" });
        return fledermausToken;
    };

    // +++ 7 - RÜCKVERWANDLUNG +++++++++++++++++++++++++++++++++

    const rueckverwandeln = async effect => {
        if (!effect || !istAktiverGM() || effect.getFlag("dsk", "fledermausleib") !== true) return false;

        const casterActor = effect.parent;
        if (!casterActor) return false;

        const sceneId = effect.getFlag("dsk", "sceneId");
        const originalTokenUuid = effect.getFlag("dsk", "originalTokenUuid");
        const originalTokenId = effect.getFlag("dsk", "originalTokenId");
        const fledermausTokenUuid = effect.getFlag("dsk", "fledermausTokenUuid");
        const fledermausTokenId = effect.getFlag("dsk", "fledermausTokenId");
        const fledermausActorUuid = effect.getFlag("dsk", "fledermausActorUuid");
        const sessionId = effect.getFlag("dsk", "sessionId");
        const scene = game.scenes.get(sceneId) || canvas.scene;

        const fledermausToken = await ladeTokenDokument({ tokenUuid: fledermausTokenUuid, tokenId: fledermausTokenId, sceneId });
        const fledermausTokenActor = fledermausToken?.actor || null;

        if (fledermausTokenActor) {
            const fledermausLeP = liesStat(fledermausTokenActor, "LeP"), fledermausAeP = liesStat(fledermausTokenActor, "AeP");
            const casterLeP = liesStat(casterActor, "LeP"), casterAeP = liesStat(casterActor, "AeP");

            await casterActor.update({
                "system.stats.LeP.value": berechneProzentwert({
                    quellWert: fledermausLeP.value, quellMaximum: fledermausLeP.max,
                    zielMaximum: casterLeP.max, minimum: fledermausLeP.value > 0 ? 1 : 0
                }),
                "system.stats.AeP.value": berechneProzentwert({
                    quellWert: fledermausAeP.value, quellMaximum: fledermausAeP.max,
                    zielMaximum: casterAeP.max, minimum: 0
                })
            }, { dskFledermausSync: true });
        }

        const originalToken = await ladeTokenDokument({ tokenUuid: originalTokenUuid, tokenId: originalTokenId, sceneId });
        if (originalToken) await originalToken.update({ hidden: false });

        if (scene && fledermausTokenId && scene.tokens.get(fledermausTokenId)) {
            await scene.deleteEmbeddedDocuments("Token", [fledermausTokenId], { dskFledermausCleanup: true });
        }

        let fledermausActor = await ladeActor(fledermausActorUuid);
        if (!fledermausActor) fledermausActor = findeImportierteFledermaus();
        if (fledermausActor && sessionId) await entferneRechteSitzung({ fledermausActor, sessionId });

        return true;
    };

    // +++ 8 - WÄCHTER-HOOKS +++++++++++++++++++++++++++++++++++

    if (globalThis._dskFledermausUpdateHook) Hooks.off("updateActor", globalThis._dskFledermausUpdateHook);

    globalThis._dskFledermausUpdateHook = Hooks.on("updateActor", async (updatedActor, changes, options) => {
        if (!istAktiverGM() || options?.dskFledermausSync || options?.dskFledermausSetup) return;

        const lePChange = foundry.utils.getProperty(changes, "system.stats.LeP.value");
        const aePChange = foundry.utils.getProperty(changes, "system.stats.AeP.value");
        if (lePChange === undefined && aePChange === undefined) return;

        const casterUuid = updatedActor.getFlag("dsk", "isFledermausVon");

        if (casterUuid) {
            const casterActor = await ladeActor(casterUuid);
            if (!casterActor) return;

            const updateDaten = {};

            if (lePChange !== undefined) {
                const fledermausLeP = liesStat(updatedActor, "LeP"), casterLeP = liesStat(casterActor, "LeP");
                updateDaten["system.stats.LeP.value"] = berechneProzentwert({
                    quellWert: lePChange, quellMaximum: fledermausLeP.max,
                    zielMaximum: casterLeP.max, minimum: Number(lePChange) > 0 ? 1 : 0
                });
            }

            if (aePChange !== undefined) {
                const fledermausAeP = liesStat(updatedActor, "AeP"), casterAeP = liesStat(casterActor, "AeP");
                updateDaten["system.stats.AeP.value"] = berechneProzentwert({
                    quellWert: aePChange, quellMaximum: fledermausAeP.max,
                    zielMaximum: casterAeP.max, minimum: 0
                });
            }

            if (Object.keys(updateDaten).length) await casterActor.update(updateDaten, { dskFledermausSync: true });
            return;
        }

        const fledermausEffekt = updatedActor.effects.find(effect => effect.getFlag("dsk", "fledermausleib") === true);
        if (!fledermausEffekt) return;

        const fledermausToken = await ladeTokenDokument({
            tokenUuid: fledermausEffekt.getFlag("dsk", "fledermausTokenUuid"),
            tokenId: fledermausEffekt.getFlag("dsk", "fledermausTokenId"),
            sceneId: fledermausEffekt.getFlag("dsk", "sceneId")
        });

        const fledermausTokenActor = fledermausToken?.actor;
        if (!fledermausTokenActor) return;

        const updateDaten = {};

        if (lePChange !== undefined) {
            const casterLeP = liesStat(updatedActor, "LeP"), fledermausLeP = liesStat(fledermausTokenActor, "LeP");
            updateDaten["system.stats.LeP.value"] = berechneProzentwert({
                quellWert: lePChange, quellMaximum: casterLeP.max,
                zielMaximum: fledermausLeP.max, minimum: Number(lePChange) > 0 ? 1 : 0
            });
        }

        if (aePChange !== undefined) {
            const casterAeP = liesStat(updatedActor, "AeP"), fledermausAeP = liesStat(fledermausTokenActor, "AeP");
            updateDaten["system.stats.AeP.value"] = berechneProzentwert({
                quellWert: aePChange, quellMaximum: casterAeP.max,
                zielMaximum: fledermausAeP.max, minimum: 0
            });
        }

        if (Object.keys(updateDaten).length) {
            await fledermausTokenActor.update(updateDaten, { dskFledermausSync: true });
        }
    });

    if (globalThis._dskFledermausDeleteEffectHook) Hooks.off("deleteActiveEffect", globalThis._dskFledermausDeleteEffectHook);

    globalThis._dskFledermausDeleteEffectHook = Hooks.on("deleteActiveEffect", async effect => {
        if (!istAktiverGM()) return;
        try { await rueckverwandeln(effect); }
        catch (error) { console.error("Fledermausleib: Rückverwandlung fehlgeschlagen.", error); }
    });

    if (globalThis._dskFledermausDeleteTokenHook) Hooks.off("deleteToken", globalThis._dskFledermausDeleteTokenHook);

    globalThis._dskFledermausDeleteTokenHook = Hooks.on("deleteToken", async (tokenDokument, options) => {
        if (!istAktiverGM() || options?.dskFledermausCleanup || tokenDokument.getFlag("dsk", "fledermausleib") !== true) return;

        const casterUuid = tokenDokument.getFlag("dsk", "isFledermausVon");
        const sessionId = tokenDokument.getFlag("dsk", "fledermausleibSessionId");
        const casterActor = await ladeActor(casterUuid);

        if (casterActor) {
            const fledermausEffekt = casterActor.effects.find(effect =>
                effect.getFlag("dsk", "fledermausleib") === true &&
                effect.getFlag("dsk", "sessionId") === sessionId
            );

            if (fledermausEffekt) {
                await fledermausEffekt.delete();
                return;
            }
        }

        const fledermausActor = game.actors.get(tokenDokument.actorId) || findeImportierteFledermaus();
        if (fledermausActor && sessionId) await entferneRechteSitzung({ fledermausActor, sessionId });
    });

    // +++ 9 - VERWANDLUNG ANWENDEN ++++++++++++++++++++++++++++

    const verarbeiteAnfrage = async (casterActor, daten) => {
        if (!casterActor || !daten || !istAktiverGM()) return false;

        if (daten.sceneId && daten.sceneId !== canvas.scene?.id) {
            ui.notifications.warn(`Luna sagt 🌙: Die Anfrage von „${casterActor.name}“ gehört zu einer anderen Szene.`);
            return false;
        }

        const casterToken = DSK_FW.Token.Finde(casterActor, daten.casterTokenId, daten.casterTokenUuid);

        if (!casterToken) {
            ui.notifications.warn(`Luna sagt 🌙: Der Token von „${casterActor.name}“ wurde auf der aktiven Szene nicht gefunden!`);
            return false;
        }

        const vorhandenerEffekt = casterActor.effects.find(effect =>
            effect.getFlag("dsk", "fledermausleib") === true ||
            (effect.name || effect.label || "") === vollerName
        );

        if (vorhandenerEffekt) {
            ui.notifications.warn(`Luna sagt 🌙: ${casterActor.name} befindet sich bereits im Fledermausleib!`);
            return false;
        }

        const qs = Math.max(1, Math.floor(Number(daten.qs) || 1));
        const casterName = daten.casterName || DSK_FW.ResolveTokenName(casterActor);
        const sessionId = `fledermaus-${Date.now()}-${foundry.utils.randomID()}`;
        let fledermausActor = null, fledermausToken = null, originalVersteckt = false;

        try {
            fledermausActor = await ladeOderImportiereFledermaus();

            const userIds = new Set(DSK_FW.Empfaenger.Besitzer(casterActor));
            if (daten.requestedByUserId && game.users.get(daten.requestedByUserId)) userIds.add(daten.requestedByUserId);

            await fuegeRechteSitzungHinzu({ fledermausActor, sessionId, userIds: [...userIds] });
            fledermausToken = await erzeugeFledermausToken({ casterActor, casterToken, fledermausActor, sessionId });

            await casterToken.document.update({ hidden: true });
            originalVersteckt = true;

            const beschreibung =
                `Der Leib von <b>${casterName}</b> zerfällt in Fledermäuse. Eine dieser Fledermäuse ist der Wirkende.` +
                `<br><br>LeP und AeP bleiben prozentual mit der Fledermaus verbunden.` +
                `<br><br><b>Bewegungsaktion:</b> Fliegen` +
                `<br><b>Wirkungsdauer:</b> ${qs * 5} Minuten`;

            const erzeugterEffekt = await DSK_FW.Effekt.Anwenden({
                name: vollerName, ahne, beschreibung, gabeZiel: "", qs, ziel: casterActor,
                changes: [{
                    key: "flags.dsk.status", mode: CONST.ACTIVE_EFFECT_MODES.OVERRIDE,
                    value: "Verwandelt in Fledermaus", priority: 20
                }],
                duration: { seconds: qs * 5 * 60, startTime: game.time.worldTime },
                origin: casterActor.uuid, showIcon: 1,
                flags: {
                    core: { statusId: "fledermausleib" },
                    dsk: {
                        fledermausleib: true, ahne, qs, casterUuid: casterActor.uuid,
                        sceneId: canvas.scene.id,
                        originalTokenUuid: casterToken.document.uuid, originalTokenId: casterToken.id,
                        fledermausActorUuid: fledermausActor.uuid, fledermausActorId: fledermausActor.id,
                        fledermausTokenUuid: fledermausToken.uuid, fledermausTokenId: fledermausToken.id,
                        sessionId, requestedByUserId: daten.requestedByUserId || null,
                        wirkungsende: {
                            sfName: endeKey, basisEffektName: vollerName,
                            beschreibungFuerEnde: endeText
                        }
                    }
                }
            });

            if (!erzeugterEffekt) throw new Error("Der Fledermausleib-Effekt konnte nicht erstellt werden.");

            await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
                messageId: daten.messageId, gabenName: vollerName, ahne,
                beschreibung: basisBeschreibung, wirkender: casterName,
                ziele: [{
                    name: casterName,
                    rolle: "In eine Fledermaus verwandelt"
                }],
                misserfolge: [],
                dauerText: `${qs * 5} Minuten (${qs} QS × 5 Min.)`,
                erfolgreich: true
            });

            ui.notifications.info(`Luna sagt 🌙: ${casterName} wurde in eine Fledermaus verwandelt.`);
            return true;

        } catch (error) {
            console.error("Fledermausleib: Verwandlung fehlgeschlagen.", error);

            if (originalVersteckt) {
                try { await casterToken.document.update({ hidden: false }); }
                catch (folgeFehler) {
                    console.error("Fledermausleib: Originaltoken konnte nicht wieder eingeblendet werden.", folgeFehler);
                }
            }

            if (fledermausToken && canvas.scene?.tokens.get(fledermausToken.id)) {
                try {
                    await canvas.scene.deleteEmbeddedDocuments(
                        "Token", [fledermausToken.id], { dskFledermausCleanup: true }
                    );
                } catch (folgeFehler) {
                    console.error("Fledermausleib: Fledermaus-Token konnte nicht entfernt werden.", folgeFehler);
                }
            }

            if (fledermausActor && sessionId) {
                try { await entferneRechteSitzung({ fledermausActor, sessionId }); }
                catch (folgeFehler) {
                    console.error("Fledermausleib: Rechte konnten nicht zurückgesetzt werden.", folgeFehler);
                }
            }

            if (daten.messageId) {
                await DSK_FW.GabenUI.AnfrageKarteAktualisieren({
                    messageId: daten.messageId, gabenName: vollerName, ahne,
                    beschreibung: basisBeschreibung, wirkender: casterName,
                    ziele: [],
                    misserfolge: [{
                        name: casterName,
                        grund: "Verwandlung konnte nicht vollständig durchgeführt werden"
                    }],
                    dauerText: `${qs * 5} Minuten (${qs} QS × 5 Min.)`,
                    erfolgreich: false
                }).catch(() => {});
            }

            ui.notifications.error("Luna sagt 🌙: Die Verwandlung konnte nicht vollständig durchgeführt werden!");
            return true;
        }
    };

    // +++ 10 - GM-MODUS +++++++++++++++++++++++++++++++++++++++

    if (game.user.isGM) {
        const anfragen = DSK_FW.GMAnfrage.Finden(flagKey);

        if (anfragen.length) {
            for (const anfrageActor of anfragen) {
                const daten = DSK_FW.GMAnfrage.Lesen(anfrageActor, flagKey);
                if (!daten) continue;

                if (await verarbeiteAnfrage(anfrageActor, daten)) {
                    await DSK_FW.GMAnfrage.Loeschen(anfrageActor, flagKey);
                }
            }
            return;
        }
    }

    // +++ 11 - WIRKENDER UND QS +++++++++++++++++++++++++++++++

    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor =
            canvas.tokens.placeables.map(token => token.actor)
                .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) ||
            null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst deinen Token aus!");
    if (!game.user.isGM && !casterActor.isOwner) {
        return ui.notifications.warn("Luna sagt 🌙: Du besitzt keine ausreichenden Rechte für diesen Akteur!");
    }

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Der Wirkende braucht einen Token auf der aktuellen Szene!");

    const casterName = DSK_FW.ResolveTokenName(casterActor);
    const vorhandenerEffekt = casterActor.effects.find(effect =>
        effect.getFlag("dsk", "fledermausleib") === true ||
        (effect.name || effect.label || "") === vollerName
    );

    if (vorhandenerEffekt) {
        return ui.notifications.warn(`Luna sagt 🌙: ${casterName} befindet sich bereits im Fledermausleib!`);
    }

    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor, gabenName,
        suchbegriffe: ["Fledermausleib Probe", "Fledermausleib"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0, protokollieren: true
    });

    if (qs <= 0) {
        return ui.notifications.warn(
            "Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!"
        );
    }

    // +++ 12 - GEMEINSAME KARTE ÜBER BLOCK 19.8 +++++++++++++++

    const dauerText = `${qs * 5} Minuten (${qs} QS × 5 Min.)`;
    const gmLink = DSK_FW.GabenUI.GMMakroButton(
        macroUuid,
        "Effekt anwenden",
        "Das Makro muss durch die Spielleitung ausgeführt werden."
    );

    const nachricht = await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName, ahne, beschreibung: basisBeschreibung,
        wirkender: casterName,
        ziele: [{
            name: casterName,
            rolle: "Zu verwandelnder Wirkender"
        }],
        misserfolge: [], dauerText, gmLink,
        gmBereich: !game.user.isGM,
        anfragenderUserId: game.user.id
    });

    if (!nachricht) {
        await raeumeQSAuf(casterActor);
        return ui.notifications.error("Luna sagt 🌙: Die Wirkungskarte konnte nicht erstellt werden!");
    }

    // +++ 13 - ANFRAGEDATEN ++++++++++++++++++++++++++++++++++++

    const anfrageDaten = {
        casterUuid: casterActor.uuid, casterName,
        casterTokenId: casterToken.id,
        casterTokenUuid: casterToken.document?.uuid || casterToken.uuid || null,
        qs, sceneId: canvas.scene?.id || null,
        requestedByUserId: game.user.id,
        messageId: nachricht.id,
        macroUuid, erstellt: Date.now()
    };

    // +++ 14 - GM DIREKT ODER ANFRAGE SPEICHERN +++++++++++++++

    if (game.user.isGM) {
        await verarbeiteAnfrage(casterActor, anfrageDaten);
        await raeumeQSAuf(casterActor);
        return;
    }

    await DSK_FW.GMAnfrage.Speichern(casterActor, flagKey, anfrageDaten);

    // +++ 15 - QS AUFRÄUMEN +++++++++++++++++++++++++++++++++++

    await raeumeQSAuf(casterActor);
    ui.notifications.info("Luna sagt 🌙: Die Verwandlung wurde bei der Spielleitung beantragt.");

}).call(this);
